-- Overland Core initial migration (matches prisma/schema.prisma exactly)
-- Generated by hand to match the Prisma schema field by field. Prisma 5
-- PostgreSQL DDL conventions are followed: TEXT for String, TIMESTAMP(3)
-- for DateTime, JSONB for Json, SERIAL for Int @default(autoincrement()),
-- DEFAULT CURRENT_TIMESTAMP for DateTime @default(now()). Columns with
-- @default(cuid()) have no database default; the id is generated by the
-- Prisma Client. Columns with @updatedAt have no database default; the
-- Prisma Client sets them on update.
-- Apply with: npx prisma migrate deploy
-- (or npx prisma migrate dev against a live PostgreSQL instance).

CREATE TYPE "TeamStatus" AS ENUM ('ACTIVE', 'INACTIVE', 'SUSPENDED', 'REMOVED');
CREATE TYPE "PermissionGroupName" AS ENUM ('Owner', 'Executive', 'Administration', 'Moderation', 'Development', 'Support', 'Rewards_Management');
CREATE TYPE "CurrencyKind" AS ENUM ('OVERPOINTS', 'OVERCREDITS');
CREATE TYPE "TransactionSource" AS ENUM ('DAILY_CHECKIN', 'PARTICIPATION', 'HELPFUL_ANSWER', 'EVENT', 'WEEKLY_CHALLENGE', 'CONTRIBUTION', 'SOCIAL_SUBMISSION', 'REFERRAL', 'REFERRAL_RETENTION', 'REFERRAL_COMRADE', 'REWARD_CLAIM', 'ADMIN_ADJUSTMENT', 'ACHIEVEMENT', 'STREAK_BONUS');
CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT', 'ACTIVE', 'ENDED', 'CANCELLED');
CREATE TYPE "SubmissionStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "RewardClaimStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'FULFILLED', 'CANCELLED');
CREATE TYPE "TicketStatus" AS ENUM ('OPEN', 'CLAIMED', 'CLOSED', 'ARCHIVED');
CREATE TYPE "ModerationActionType" AS ENUM ('WARN', 'TIMEOUT', 'KICK', 'BAN', 'UNBAN', 'NOTE', 'LOCKDOWN');
CREATE TYPE "AchievementKind" AS ENUM ('VERIFICATION', 'CONTRIBUTION', 'REFERRAL', 'SOCIAL', 'MILESTONE', 'EVENT', 'STREAK', 'CUSTOM');
CREATE TYPE "LeaderboardPeriod" AS ENUM ('LIFETIME', 'MONTHLY', 'WEEKLY');

-- 1. users (model User)
CREATE TABLE "users" (
    "id" TEXT NOT NULL,
    "discordId" TEXT NOT NULL,
    "username" TEXT NOT NULL,
    "avatarUrl" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "users_discordId_key" ON "users"("discordId");

-- 2. discord_members (model DiscordMember)
CREATE TABLE "discord_members" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "guildId" TEXT NOT NULL,
    "joinedAt" TIMESTAMP(3),
    "verifiedAt" TIMESTAMP(3),
    "xFollowVerified" BOOLEAN NOT NULL DEFAULT false,
    "xFollowVerifiedAt" TIMESTAMP(3),
    "isSuspicious" BOOLEAN NOT NULL DEFAULT false,
    "lastMessageAt" TIMESTAMP(3),
    "messageCount" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "discord_members_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "discord_members_userId_key" ON "discord_members"("userId");
CREATE INDEX "discord_members_guildId_idx" ON "discord_members"("guildId");

-- 3. roles (model Role, self-referencing requiresRoleId)
CREATE TABLE "roles" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "discordRoleId" TEXT,
    "description" TEXT,
    "isInternal" BOOLEAN NOT NULL DEFAULT false,
    "isSelfAssignable" BOOLEAN NOT NULL DEFAULT false,
    "requiresRoleId" TEXT,
    "minOverpoints" INTEGER,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "roles_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "roles_name_key" ON "roles"("name");
CREATE UNIQUE INDEX "roles_discordRoleId_key" ON "roles"("discordRoleId");

-- 4. member_roles (model MemberRole)
CREATE TABLE "member_roles" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "roleId" TEXT NOT NULL,
    "grantedBy" TEXT,
    "grantedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMP(3),
    CONSTRAINT "member_roles_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "member_roles_memberId_roleId_key" ON "member_roles"("memberId", "roleId");
CREATE INDEX "member_roles_memberId_idx" ON "member_roles"("memberId");

-- 5. role_history (model RoleHistory)
CREATE TABLE "role_history" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "roleId" TEXT NOT NULL,
    "action" TEXT NOT NULL,
    "actorId" TEXT,
    "reason" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "role_history_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "role_history_memberId_idx" ON "role_history"("memberId");

-- 6. permission_groups (model PermissionGroup)
CREATE TABLE "permission_groups" (
    "id" TEXT NOT NULL,
    "name" "PermissionGroupName" NOT NULL,
    "description" TEXT,
    CONSTRAINT "permission_groups_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "permission_groups_name_key" ON "permission_groups"("name");

-- 7. permissions (model Permission)
CREATE TABLE "permissions" (
    "id" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "description" TEXT,
    "groupId" TEXT NOT NULL,
    CONSTRAINT "permissions_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "permissions_key_key" ON "permissions"("key");

-- 8. internal_team_members (model InternalTeamMember)
CREATE TABLE "internal_team_members" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "discordId" TEXT NOT NULL,
    "username" TEXT NOT NULL,
    "publicRole" TEXT NOT NULL,
    "jobTitle" TEXT NOT NULL,
    "department" TEXT NOT NULL,
    "responsibilities" TEXT,
    "groupId" TEXT NOT NULL,
    "status" "TeamStatus" NOT NULL DEFAULT 'ACTIVE',
    "addedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "internal_team_members_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "internal_team_members_memberId_key" ON "internal_team_members"("memberId");
CREATE UNIQUE INDEX "internal_team_members_discordId_key" ON "internal_team_members"("discordId");

-- 9. point_balances (model PointBalance)
CREATE TABLE "point_balances" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "overpoints" INTEGER NOT NULL DEFAULT 0,
    "overcredits" INTEGER NOT NULL DEFAULT 0,
    "communityPoints" INTEGER NOT NULL DEFAULT 0,
    "socialPoints" INTEGER NOT NULL DEFAULT 0,
    "referralPoints" INTEGER NOT NULL DEFAULT 0,
    "contributionPoints" INTEGER NOT NULL DEFAULT 0,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "point_balances_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "point_balances_memberId_key" ON "point_balances"("memberId");

-- 10. point_transactions (model PointTransaction)
CREATE TABLE "point_transactions" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "currency" "CurrencyKind" NOT NULL,
    "category" TEXT NOT NULL,
    "amount" INTEGER NOT NULL,
    "balanceAfter" INTEGER NOT NULL,
    "source" "TransactionSource" NOT NULL,
    "idempotencyKey" TEXT NOT NULL,
    "reason" TEXT,
    "actorId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "point_transactions_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "point_transactions_idempotencyKey_key" ON "point_transactions"("idempotencyKey");
CREATE INDEX "point_transactions_memberId_createdAt_idx" ON "point_transactions"("memberId", "createdAt");
CREATE INDEX "point_transactions_idempotencyKey_idx" ON "point_transactions"("idempotencyKey");

-- 11. campaigns (model Campaign)
CREATE TABLE "campaigns" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "objectives" TEXT,
    "startsAt" TIMESTAMP(3) NOT NULL,
    "endsAt" TIMESTAMP(3) NOT NULL,
    "tasks" JSONB,
    "pointReward" INTEGER NOT NULL DEFAULT 0,
    "submissionRequirements" TEXT,
    "status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',
    "createdBy" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "campaigns_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "campaigns_status_idx" ON "campaigns"("status");

-- 12. campaign_submissions (model CampaignSubmission)
CREATE TABLE "campaign_submissions" (
    "id" TEXT NOT NULL,
    "campaignId" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "content" TEXT NOT NULL,
    "linkUrl" TEXT,
    "imageUrl" TEXT,
    "status" "SubmissionStatus" NOT NULL DEFAULT 'PENDING',
    "feedback" TEXT,
    "pointsAwarded" INTEGER NOT NULL DEFAULT 0,
    "reviewedBy" TEXT,
    "reviewedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "campaign_submissions_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "campaign_submissions_campaignId_status_idx" ON "campaign_submissions"("campaignId", "status");

-- 13. referrals (model Referral)
CREATE TABLE "referrals" (
    "id" TEXT NOT NULL,
    "referrerId" TEXT NOT NULL,
    "referredId" TEXT NOT NULL,
    "inviteCode" TEXT NOT NULL,
    "verified" BOOLEAN NOT NULL DEFAULT false,
    "verifiedAt" TIMESTAMP(3),
    "retained7d" BOOLEAN NOT NULL DEFAULT false,
    "becameComrade" BOOLEAN NOT NULL DEFAULT false,
    "suspicious" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "referrals_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "referrals_referrerId_referredId_key" ON "referrals"("referrerId", "referredId");
CREATE INDEX "referrals_inviteCode_idx" ON "referrals"("inviteCode");

-- 14. rewards (model Reward)
CREATE TABLE "rewards" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "imageUrl" TEXT,
    "costOvercredits" INTEGER NOT NULL,
    "stock" INTEGER,
    "eligibility" TEXT,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "rewards_pkey" PRIMARY KEY ("id")
);

-- 15. reward_claims (model RewardClaim)
CREATE TABLE "reward_claims" (
    "id" TEXT NOT NULL,
    "rewardId" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "status" "RewardClaimStatus" NOT NULL DEFAULT 'PENDING',
    "costOvercredits" INTEGER NOT NULL,
    "idempotencyKey" TEXT NOT NULL,
    "reviewedBy" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "reward_claims_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "reward_claims_idempotencyKey_key" ON "reward_claims"("idempotencyKey");
CREATE INDEX "reward_claims_memberId_idx" ON "reward_claims"("memberId");

-- 16. achievements (model Achievement)
CREATE TABLE "achievements" (
    "id" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "kind" "AchievementKind" NOT NULL,
    "threshold" INTEGER NOT NULL DEFAULT 1,
    "overpointsReward" INTEGER NOT NULL DEFAULT 0,
    "overcreditsReward" INTEGER NOT NULL DEFAULT 0,
    "active" BOOLEAN NOT NULL DEFAULT true,
    CONSTRAINT "achievements_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "achievements_key_key" ON "achievements"("key");

-- 17. member_achievements (model MemberAchievement)
CREATE TABLE "member_achievements" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "achievementId" TEXT NOT NULL,
    "awardedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "member_achievements_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "member_achievements_memberId_achievementId_key" ON "member_achievements"("memberId", "achievementId");

-- 18. daily_checkins (model DailyCheckin)
CREATE TABLE "daily_checkins" (
    "id" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "date" DATE NOT NULL,
    "streak" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "daily_checkins_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "daily_checkins_memberId_date_key" ON "daily_checkins"("memberId", "date");

-- 19. leaderboard_snapshots (model LeaderboardSnapshot, no foreign keys)
CREATE TABLE "leaderboard_snapshots" (
    "id" TEXT NOT NULL,
    "period" "LeaderboardPeriod" NOT NULL,
    "category" TEXT NOT NULL,
    "periodKey" TEXT NOT NULL,
    "memberId" TEXT NOT NULL,
    "rank" INTEGER NOT NULL,
    "score" INTEGER NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "leaderboard_snapshots_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "leaderboard_snapshots_period_category_periodKey_rank_idx" ON "leaderboard_snapshots"("period", "category", "periodKey", "rank");

-- 20. tickets (model Ticket)
CREATE TABLE "tickets" (
    "id" TEXT NOT NULL,
    "number" SERIAL NOT NULL,
    "category" TEXT NOT NULL,
    "channelId" TEXT,
    "memberId" TEXT NOT NULL,
    "status" "TicketStatus" NOT NULL DEFAULT 'OPEN',
    "claimedBy" TEXT,
    "rating" INTEGER,
    "firstResponseAt" TIMESTAMP(3),
    "closedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "tickets_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "tickets_number_key" ON "tickets"("number");
CREATE UNIQUE INDEX "tickets_channelId_key" ON "tickets"("channelId");

-- 21. ticket_messages (model TicketMessage)
CREATE TABLE "ticket_messages" (
    "id" TEXT NOT NULL,
    "ticketId" TEXT NOT NULL,
    "authorId" TEXT NOT NULL,
    "content" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ticket_messages_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "ticket_messages_ticketId_idx" ON "ticket_messages"("ticketId");

-- 22. moderation_actions (model ModerationAction)
CREATE TABLE "moderation_actions" (
    "id" TEXT NOT NULL,
    "targetId" TEXT NOT NULL,
    "actorId" TEXT NOT NULL,
    "type" "ModerationActionType" NOT NULL,
    "reason" TEXT,
    "durationMinutes" INTEGER,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "moderation_actions_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "moderation_actions_targetId_idx" ON "moderation_actions"("targetId");

-- 23. x_posts (model XPost)
CREATE TABLE "x_posts" (
    "id" TEXT NOT NULL,
    "postId" TEXT NOT NULL,
    "authorUsername" TEXT NOT NULL,
    "text" TEXT NOT NULL,
    "url" TEXT NOT NULL,
    "mediaUrls" JSONB,
    "isReply" BOOLEAN NOT NULL DEFAULT false,
    "isRepost" BOOLEAN NOT NULL DEFAULT false,
    "announcedAt" TIMESTAMP(3),
    "announcedChannelId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "x_posts_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "x_posts_postId_key" ON "x_posts"("postId");
CREATE INDEX "x_posts_createdAt_idx" ON "x_posts"("createdAt");

-- 24. bot_configuration (model BotConfiguration)
CREATE TABLE "bot_configuration" (
    "id" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "value" JSONB NOT NULL,
    "updatedBy" TEXT,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "bot_configuration_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "bot_configuration_key_key" ON "bot_configuration"("key");

-- 25. audit_logs (model AuditLog)
CREATE TABLE "audit_logs" (
    "id" TEXT NOT NULL,
    "actorId" TEXT,
    "action" TEXT NOT NULL,
    "entityType" TEXT,
    "entityId" TEXT,
    "details" JSONB,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "audit_logs_actorId_createdAt_idx" ON "audit_logs"("actorId", "createdAt");

-- Foreign keys (onDelete behaviour copied from schema.prisma)
ALTER TABLE "discord_members" ADD CONSTRAINT "discord_members_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "roles" ADD CONSTRAINT "roles_requiresRoleId_fkey" FOREIGN KEY ("requiresRoleId") REFERENCES "roles"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "member_roles" ADD CONSTRAINT "member_roles_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "member_roles" ADD CONSTRAINT "member_roles_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "role_history" ADD CONSTRAINT "role_history_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "role_history" ADD CONSTRAINT "role_history_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "roles"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "permissions" ADD CONSTRAINT "permissions_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "permission_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "internal_team_members" ADD CONSTRAINT "internal_team_members_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "internal_team_members" ADD CONSTRAINT "internal_team_members_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "permission_groups"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "point_balances" ADD CONSTRAINT "point_balances_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "point_transactions" ADD CONSTRAINT "point_transactions_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "campaign_submissions" ADD CONSTRAINT "campaign_submissions_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "campaigns"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "campaign_submissions" ADD CONSTRAINT "campaign_submissions_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "referrals" ADD CONSTRAINT "referrals_referrerId_fkey" FOREIGN KEY ("referrerId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "referrals" ADD CONSTRAINT "referrals_referredId_fkey" FOREIGN KEY ("referredId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "reward_claims" ADD CONSTRAINT "reward_claims_rewardId_fkey" FOREIGN KEY ("rewardId") REFERENCES "rewards"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "reward_claims" ADD CONSTRAINT "reward_claims_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "member_achievements" ADD CONSTRAINT "member_achievements_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "member_achievements" ADD CONSTRAINT "member_achievements_achievementId_fkey" FOREIGN KEY ("achievementId") REFERENCES "achievements"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "daily_checkins" ADD CONSTRAINT "daily_checkins_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "tickets" ADD CONSTRAINT "tickets_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "discord_members"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ticket_messages" ADD CONSTRAINT "ticket_messages_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "tickets"("id") ON DELETE CASCADE ON UPDATE CASCADE;
